cat > src/main/java/GameOfLife.java <<'EOF'
import java.util.Set;
import java.util.stream.Collectors;

public class GameOfLife {

    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
        return livingCells.stream()
                .filter(cell -> livingNeighboursOf(cell, livingCells) == 2)
                .collect(Collectors.toSet());
    }

    private long livingNeighboursOf(Cell cell, Set<Cell> livingCells) {
        return livingCells.stream().filter(other -> isNeighbourOf(cell, other)).count();
    }

    private boolean isNeighbourOf(Cell cell, Cell other) {
        if (cell.equals(other)) {
            return false;
        }
        return Math.abs(cell.x() - other.x()) <= 1 && Math.abs(cell.y() - other.y()) <= 1;
    }
}
EOF
