import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.io.IOException;
import java.util.LinkedHashSet;
import java.util.Set;

public final class GameOfLifeCli {

    private static final String ALIVE_CELLS = "aliveCells";
    private static final ObjectMapper MAPPER = new ObjectMapper();

    private GameOfLifeCli() {
    }

    public static void main(String[] args) throws IOException {
        JsonNode request = MAPPER.readTree(System.in);
        Set<Cell> cells = readCells(request.get(ALIVE_CELLS));
        System.out.print(MAPPER.writeValueAsString(writeCells(new GameOfLife().nextGeneration(cells))));
    }

    private static Set<Cell> readCells(JsonNode aliveCells) {
        Set<Cell> cells = new LinkedHashSet<>();
        for (JsonNode cell : aliveCells) {
            cells.add(new Cell(cell.get(0).asInt(), cell.get(1).asInt()));
        }
        return cells;
    }

    private static ObjectNode writeCells(Set<Cell> cells) {
        ObjectNode response = MAPPER.createObjectNode();
        ArrayNode aliveCells = response.putArray(ALIVE_CELLS);
        for (Cell cell : cells) {
            ArrayNode pair = aliveCells.addArray();
            pair.add(cell.x());
            pair.add(cell.y());
        }
        return response;
    }
}
